D.guides.priest = {
 {
  id="pri-holy-wh30",
  spec="Holy",
  label="Holy · Wowhead level 30 healer 0/21/0",
  kind="exact-order",
  default=true,
  note="Exact order from the guide text (Spanklord, updated 2026-10-06). Covers levels 10–30 only.",
  priorities="All 21 points go into Holy so the 21st point reaches Spirit of Redemption. Improved Renew comes first because Renew is the questing heal and the tank HoT. Next comes Holy Specialization 2/5 to open row 2, then Divine Fury 5/5 for a faster Smite and Heal, then the rest of Holy Specialization. After that: Holy Nova, Inspiration 3/3, Holy Reach 2/2, then Binding Heal (needs 15 Holy points) to heal yourself and the tank in one cast. Wand Specialization (Discipline) is still the best questing talent, but two points there leave you at 19 Holy, one short of Spirit of Redemption. The guide says to take the wand points while you mostly quest and respec later. Legacy bonus points go to Litany of Light, then Wand Specialization or Spiritual Guidance. Prayer of Mending (31 points) is out of reach at 30.",
  source={
   site="Wowhead",
   author="Spanklord",
   title="Level 30 Holy Priest Guide: Talents, Rotation and Gearing - Forever",
   url="https://www.wowhead.com/forever/guide/classes/priest/holy/level-30-healer-overview",
   updated="2026-10-06",
   scope="10-30",
   purpose="dungeon healing while leveling"
  },
  order={"improved-renew","improved-renew","improved-renew","holy-specialization","holy-specialization","divine-fury","divine-fury","divine-fury","divine-fury","divine-fury","holy-specialization","holy-specialization","holy-specialization","holy-nova","inspiration","inspiration","inspiration","holy-reach","holy-reach","binding-heal","spirit-of-redemption"}
 },
 {
  id="pri-holy-trio60",
  spec="Holy",
  label="Holy · Trio healer to 60 (Companion adaptation) 18/33/0",
  kind="adaptation",
  default=false,
  note="Points 1–21 are the Wowhead level 30 guide (exact). Points 22–51 are the Companion's own suggestion, built from the talents Warcraft Tavern (18/33/0) and WowVendor (19/32/0 preliminary) name for level 60: Litany of Light, Spiritual Guidance, Spiritual Healing, Prayer of Mending, then Discipline for Meditation and Mental Agility. No source publishes this exact order.",
  priorities="All 21 points go into Holy so the 21st point reaches Spirit of Redemption. Improved Renew comes first because Renew is the questing heal and the tank HoT. Next comes Holy Specialization 2/5 to open row 2, then Divine Fury 5/5 for a faster Smite and Heal, then the rest of Holy Specialization. After that: Holy Nova, Inspiration 3/3, Holy Reach 2/2, then Binding Heal (needs 15 Holy points) to heal yourself and the tank in one cast. Wand Specialization (Discipline) is still the best questing talent, but two points there leave you at 19 Holy, one short of Spirit of Redemption. The guide says to take the wand points while you mostly quest and respec later. Legacy bonus points go to Litany of Light, then Wand Specialization or Spiritual Guidance. Prayer of Mending (31 points) is out of reach at 30.",
  source={
   site="Wowhead",
   author="Spanklord",
   title="Level 30 Holy Priest Guide: Talents, Rotation and Gearing - Forever",
   url="https://www.wowhead.com/forever/guide/classes/priest/holy/level-30-healer-overview",
   updated="2026-10-06",
   scope="10-30",
   purpose="dungeon healing while leveling"
  },
  order={"improved-renew","improved-renew","improved-renew","holy-specialization","holy-specialization","divine-fury","divine-fury","divine-fury","divine-fury","divine-fury","holy-specialization","holy-specialization","holy-specialization","holy-nova","inspiration","inspiration","inspiration","holy-reach","holy-reach","binding-heal","spirit-of-redemption","litany-of-light","litany-of-light","spiritual-guidance","spiritual-guidance","spiritual-guidance","spiritual-guidance","spiritual-guidance","spiritual-healing","spiritual-healing","spiritual-healing","prayer-of-mending","improved-healing","twin-disciplines","twin-disciplines","twin-disciplines","twin-disciplines","twin-disciplines","mental-strength","mental-strength","mental-strength","mental-strength","mental-strength","meditation","meditation","meditation","mental-agility","mental-agility","mental-agility","improved-power-word-shield","improved-power-word-shield"}
 },
 {
  id="pri-holy-wv30",
  spec="Holy",
  label="Holy · WowVendor level 30 healer 0/21/0",
  kind="exact-order",
  default=false,
  note="Exact level-by-level table from the guide (Waspers). Trades Spirit of Redemption for Improved Healing and Litany of Light.",
  priorities="The guide gives a level-by-level table: L10-12 Improved Renew 3, L13-14 Holy Specialization 2, L15-19 Divine Fury 5, L20-22 finish Holy Specialization, L23-24 Inspiration 2, L25 Binding Heal, L26-28 Improved Healing 3, L29 Holy Nova, L30 Litany of Light 1. Divine Fury shortens Heal, Greater Heal, Smite and Holy Fire. Binding Heal handles the healer and the tank being hurt at the same time. Improved Healing cuts the mana cost of direct heals, and Litany of Light refunds mana when you alternate heals. The build trades Spirit of Redemption for Improved Healing and Litany of Light. Preliminary level-60 target is 19/32/0, adding Spiritual Healing, Spiritual Guidance, Spirit of Redemption, Prayer of Mending and more Litany of Light. No point order is given for that.",
  source={
   site="WowVendor",
